def solve(Lo=1.53, sigma_Lo=0.05, Tf_C=-35.0, sigma_Tf=1.0, lambda_um=6.7, c1B=1.191043e8, c2=14387.75) -> dict:
    import math

    # Planck's Law for radiance
    def L(T_K):
        return (c1B * lambda_um**-5) / (math.exp(c2 / (lambda_um * T_K)) - 1)

    # Cost function to minimize
    def J(T_C):
        T_K = T_C + 273.15
        term1 = ((Tf_C - T_C) / sigma_Tf)**2
        term2 = ((Lo - L(T_K)) / sigma_Lo)**2
        return 0.5 * (term1 + term2)

    # Grid search to find the minimum of the cost function
    best_T = Tf_C
    min_J = float('inf')

    # Search between -50 C and 0 C with 0.001 C resolution
    for i in range(-50000, 0):
        T_test = i / 1000.0
        cost = J(T_test)
        if cost < min_J:
            min_J = cost
            best_T = T_test

    return {
        "1": {"value": round(best_T), "unit": "°C"}
    }

